function validate([a, b]) {
  if (a.length !== 4) return 'a has exactly 4 values.';
  if (b.length < 4 || b.length > 100000) return 'b needs 4 to 10^5 values.';
  if (a.some(v => v < -100000 || v > 100000) || b.some(v => v < -100000 || v > 100000)) return 'Every value is between -10^5 and 10^5.';
  return null;
}

