function maxScore(a, b) {
  const best = [-Infinity, -Infinity, -Infinity, -Infinity];
  for (const value of b) {
    for (let k = 3; k >= 0; k--) {
      const before = k === 0 ? 0 : best[k - 1];
      best[k] = Math.max(best[k], before + a[k] * value);
    }
  }
  return best[3];
}

