function maxScore(a, b) {
  // Try every choice of four increasing indices.
  let top = -Infinity;
  const n = b.length;
  for (let p = 0; p < n; p++)
    for (let q = p + 1; q < n; q++)
      for (let r = q + 1; r < n; r++)
        for (let s = r + 1; s < n; s++)
          top = Math.max(top, a[0] * b[p] + a[1] * b[q] + a[2] * b[r] + a[3] * b[s]);
  return top;
}

