function generate(rand, size) {
  const large = size === 'large';
  const span = large ? 100000 : [3, 10, 100000][Math.floor(rand() * 3)];
  const any = () => Math.floor(rand() * (2 * span + 1)) - span;
  // Some inputs give b a single sign, so the best choice may be forced to take poor products.
  const sign = [0, 0, 1, -1][Math.floor(rand() * 4)];
  const a = Array.from({ length: 4 }, any);
  const n = large ? 2000 : 4 + Math.floor(rand() * 6);
  const b = Array.from({ length: n }, () => sign === 0 ? any() : sign * Math.abs(any()));
  return [a, b];
}
